import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let s = conc.Semaphore(1)
    let _ = s.acquire()
    scope {
        let t = task effect io {
            let _ = s.acquire()
            io.println("acquired")
        }
        let _ = s.release()
        let _ = t.await()
    }
    return Ok(())
}
